  <style>
    :root {
      color-scheme: light;
      --bg: #f3f6fb;
      --surface: #ffffff;
      --surface-2: #eef3f9;
      --text: #172033;
      --muted: #5f6b85;
      --border: #d8e0ec;
      --brand: #2457d6;
      --brand-strong: #1f49b2;
      --danger: #c43131;
