    button {
      font: inherit;
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      padding: 0.75rem 1rem;
      border-radius: 999px;
      background: var(--surface);
      color: var(--text);
      text-decoration: none;
      transform: translateY(-180%);
      transition: transform 0.2s ease;
      z-index: 10;
    }

    .skip-link:focus {
      transform: translateY(0);
    }

    .page {
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 2rem 1.25rem;
    }

    .preview-card {
      width: min(100%, 760px);
      background: color-mix(in srgb, var(--surface) 96%, white 4%);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow);
      padding: clamp(1.25rem, 3vw, 2rem);
      display: grid;
      gap: 1.25rem;
    }

    .preview-header {
      display: grid;
      gap: 0.35rem;
    }

    h1 {
      margin: 0;
      font-size: clamp(1.75rem, 3vw, 2.5rem);
      line-height: 1.1;
      letter-spacing: -0.03em;
    }

    .subtitle {
      margin: 0;
      color: var(--muted);
      max-width: 58ch;
      line-height: 1.5;
    }

    .image-shell {
      display: grid;
      gap: 1rem;
    }

    .image-frame {
      overflow: hidden;
      border-radius: calc(var(--radius-lg) - 4px);
      border: 1px solid var(--border);
      background: linear-gradient(160deg, #edf3ff, #dbe7ff);
    }

    .image-frame img {
      display: block;
      width: 100%;
      height: auto;
      aspect-ratio: 16 / 9;
      object-fit: cover;
    }

    .image-meta {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      flex-wrap: wrap;
      min-width: 0;
    }

    .image-details {
      display: grid;
      gap: 0.2rem;
      min-width: 0;
    }

    .image-title {
      font-size: 1.05rem;
      font-weight: 650;
      margin: 0;
    }

    .image-caption {
      margin: 0;
      color: var(--muted);
      line-height: 1.45;
    }

    .trigger {
      border: 0;
      border-radius: 999px;
      padding: 0.9rem 1.2rem;
      background: linear-gradient(180deg, var(--danger), var(--danger-strong));
      color: #fff;
      font-weight: 650;
      box-shadow: 0 10px 22px rgba(196, 49, 49, 0.22);
      cursor: pointer;
      transition: transform 0.15s ease, box-shadow 0.15s ease, background 0.15s ease;
    }

    .trigger:hover {
      transform: translateY(-1px);
      box-shadow: 0 14px 28px rgba(196, 49, 49, 0.28);
    }

    .trigger:active {
      transform: translateY(0);
    }

    .trigger:focus-visible,
    .dialog-button:focus-visible,
    .dialog-close:focus-visible {
      outline: 3px solid #1e6bff;
      outline-offset: 3px;
    }

    dialog {
      width: min(92vw, 480px);
      border: 1px solid var(--border);
      border-radius: 24px;
      padding: 0;
      box-shadow: var(--shadow);
      color: var(--text);
      background: var(--surface);
    }

    dialog::backdrop {
      background: rgba(15, 23, 42, 0.58);
      backdrop-filter: blur(6px);
    }

    .dialog-panel {
      padding: 1.25rem;
      display: grid;
      gap: 1.25rem;
    }

    .dialog-top {
      display: flex;
      align-items: start;
      justify-content: space-between;
      gap: 1rem;
    }

    .dialog-heading {
      margin: 0;
      font-size: 1.25rem;
      line-height: 1.2;
    }

    .dialog-copy {
      margin: 0.5rem 0 0;
      color: var(--muted);
      line-height: 1.5;
    }

    .dialog-close {
      border: 1px solid var(--border);
      background: var(--surface-2);
      color: var(--text);
      border-radius: 999px;
      width: 2.25rem;
      height: 2.25rem;
      display: inline-grid;
      place-items: center;
      cursor: pointer;
    }

    .dialog-actions {
      display: flex;
      justify-content: flex-end;
      gap: 0.75rem;
      flex-wrap: wrap;
    }

    .dialog-button {
      border-radius: 999px;
      border: 1px solid var(--border);
      padding: 0.85rem 1.15rem;
      background: var(--surface-2);
      color: var(--text);
      cursor: pointer;
      font-weight: 600;
    }

    .dialog-button.primary {
      border-color: transparent;
      background: linear-gradient(180deg, var(--danger), var(--danger-strong));
      color: #fff;
    }

    .visually-hidden {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    @media (max-width: 560px) {
      .image-meta {
        align-items: stretch;
      }

      .trigger {
        width: 100%;
      }

      .dialog-actions {
        flex-direction: column-reverse;
      }

      .dialog-button {
        width: 100%;
      }
    }

    @media (forced-colors: active) {
      :root {
        --bg: Canvas;
        --surface: Canvas;
        --surface-2: Canvas;
        --text: CanvasText;
        --muted: CanvasText;
        --border: CanvasText;
        --brand: ButtonText;
        --brand-strong: ButtonText;
        --danger: ButtonText;
        --danger-strong: ButtonText;
        --shadow: none;
